INSERT INTO "public"."cases" ("id", "name", "description", "first_name", "last_name", "date_of_birth", "code_status", "height_ft", "height_in", "weight_kg", "isolation_precautions_id", "language", "insurance", "employment", "relationship_status_id", "religion", "requires_interpreter", "admitting_diagnosis", "attending_provider", "inpatient_duration_days", "time_of_admission", "medical_history", "surgical_history", "allergies", "social_habits", "living_situation", "case_creation_complete", "updated_at", "created_at", "emergency_contact_name", "emergency_contact_relationship", "emergency_contact_phone", "intake_output_blocks") VALUES
	('2e66e8e8-8052-4561-bfb6-f59f3b4ac0fc', 'Case Harold Adams', 'Mr. Harold Adams, a 72-year-old male, was admitted two days ago for hyponatremia related to vomiting and diarrhea from a gastrointestinal illness he caught on a cruise. His sodium levels have been improving, but this morning, he begins to show signs of infection and early septic shock.', 'Harold', 'Adams', '1954-03-22', 'Full', 6, 2, 75, NULL, 'English', 'Medicare', 'Retired School Teacher', '88204e1d-d4b5-452e-9511-a1dcd5edc458', 'None', false, 'Hyponatremia', 'David Adler MD', 2, '09:00:00', '{Hypertension,GERD}', '{Appendectomy}', '{Seasonal}', '{}', '{"Lives with Spouse"}', false, '2026-03-19 20:20:08.403+00', '2026-03-19 20:16:45.238+00', 'Linda Adams', 'Wife', NULL, '[]'),
	('ad7f3138-3312-425a-aeac-578db75c7c43', 'Case Harold Adams', 'Harold Adams is a 72-year-old male who recently returned from a Caribbean cruise. He came to the emergency department reporting ongoing nausea and vomiting for 3 days. He has not been eating or drinking. He presents with dizziness and fatigue. He has not urinated much in the past 24 hours.', 'Harold', 'Adams', '1954-03-22', 'Full', 5, 11, 75, '006ddd48-0d46-443c-a02a-f83dd3338df1', 'English', NULL, 'Retired Teacher', NULL, 'NA', false, 'Hyponatremia', 'Chen MD', 0, '04:14:00', '{HTN,GERD}', '{"Appendectomy (1998)"}', '{"Seasonal Allergies"}', '{}', '{"Lives with Spouse"}', false, '2026-05-11 16:30:33.252+00', '2026-05-11 16:30:29.202+00', 'Linda Adams', 'Wife', NULL, '[]'),
	('3aa3d373-0368-4d66-90dd-d3c1b530347e', 'Case Maria Lopez', 'Maria presented to the emergency department with sudden onset severe epigastric and right upper quadrant pain that began after eating a high-fat meal. She reports nausea and one episode of vomiting. Pain is described as sharp, radiating to the right shoulder, 8/10.', 'Maria', 'Lopez', '1984-03-14', 'Full', 5, 3, 60, NULL, 'English', NULL, 'Nanny', NULL, 'NA', false, 'Epigastric Pain', 'Chen MD', 0, '23:39:00', '{}', '{}', '{}', '{}', '{}', false, '2026-05-12 03:40:22.744+00', '2026-05-12 03:39:37.646+00', 'NA', '', NULL, '[]'),
	('9c4d050f-f9bc-47aa-a0b3-461c12dd5337', 'Case Robert Jenkins', 'Robert presented to the emergency department with increasing shortness of breath over the past 3 days, worsened when lying flat. He reports rapids wright gain (~6 lbs in one week) and swelling in his legs. He admits to missing several doses of his "water pill."', 'Robert', 'Jenkins', '1958-11-22', 'Full', 6, 0, 95, NULL, 'English', NULL, 'unknown', NULL, 'NA', false, 'Fluid Overload', 'Chen MD', 0, '10:56:00', '{CHF,HTN,CKD3,"Medication non-adherence"}', '{}', '{}', '{}', '{}', false, '2026-05-12 14:58:25.118+00', '2026-05-12 14:56:53.029+00', '', '', NULL, '[]'),
	('37b3b78d-44cc-4391-8d6a-8d93dda40387', 'Case Susan Dickson', 'Susan Dickson is a 56-year-old female who arrived at the Emergency Department (ED) with acute chest pain. Her initial diagnostic data—labs and EKG—are inconclusive for myocardial infarction (MI), requiring further assessment and monitoring.', 'Susan', 'Dickson', '1970-03-15', 'Full', 5, 6, 88, NULL, 'English', 'Private', 'Secretary', '88204e1d-d4b5-452e-9511-a1dcd5edc458', 'NA', false, 'Chest Pain', 'Sarah Patel, MD', 0, '09:34:00', '{HTN,GERD,HLD}', '{}', '{Penicillin}', '{Former-smoker,"Social drinker, 1-2 drinks/week"}', '{"Lives with husband in single-story home"}', false, '2026-06-23 02:38:02.266+00', '2026-06-23 02:34:34.258+00', 'Anthony Dickson', 'Husband', '(555) 210-8976', '[{"intake": 0, "output": 0, "blockId": 1}, {"intake": 0, "output": 0, "blockId": 2}, {"intake": 0, "output": 0, "blockId": 3}, {"intake": 0, "output": 0, "blockId": 4}]'),
	('79fcd248-1efd-4971-b370-d4bdfd69c734', 'Case Thomas Dunn', '68-year-old male presents with progressive fatigue, dizziness, and dark tarry stools for 3 days. Reports worsening weakness with near-syncope when standing. Mild epigastric discomfort. Denies vomiting blood. Denies chest pain.', 'Thomas', 'Dunn', '1958-04-11', 'Full', 6, 1, 86, NULL, 'Englsih', 'Private', 'Construction Work', 'd8566186-5479-4874-8c22-470e8b57ed68', 'Lutheran', false, 'Acute GI Bleed with Symptomatic Anemia', 'Alex Reynolds,,, MD', 1, '14:42:00', '{HTN,"Type 2 DM","Atrial fibrillation","Stage 3 CKD","Peptic ulcer disease"}', '{}', '{Sulfa,Morphine}', '{"2-3 drinks/day","Former smoker- quit 2 years ago"}', '{"Lives alone"}', false, '2026-06-17 18:45:17.448+00', '2026-06-17 18:45:17.164+00', 'William Dunn', 'Brother', '(616) 237-8944', '[{"intake": 0, "output": 0, "blockId": 1}, {"intake": 0, "output": 0, "blockId": 2}, {"intake": 0, "output": 0, "blockId": 3}, {"intake": 0, "output": 0, "blockId": 4}]'),
	('f152f37b-80e3-4e9a-b09e-65006e9134a6', 'Case Clay Reeves', 'Sandbox For Clay', 'Clay', 'Reeves', '2024-08-17', 'Full', 8, 1, 1, NULL, 'English', 'Medicare', 'a', '88204e1d-d4b5-452e-9511-a1dcd5edc458', 'na', false, 'Playing', 'Clay Reeves,, MD', 2, '11:11:00', '{}', '{}', '{}', '{}', '{}', false, '2026-06-17 17:06:57.246+00', '2026-06-17 17:06:56.994+00', 'sd', 'sdf', '616-450-0675', '[{"intake": 0, "output": 0, "blockId": 1}, {"intake": 0, "output": 0, "blockId": 2}, {"intake": 0, "output": 0, "blockId": 3}, {"intake": 0, "output": 0, "blockId": 4}]'),
	('04ca168a-ab64-45bc-bbc0-e7bdf9d2e947', 'Case Samuel "Sam"  Dixsen', '70 year old male presents to the ER with worsening shortness of breath, orthopnea, bilateral leg swelling, weight gain after recent ED/telemetry admission for chest pain/ACS evaluation. States he has had increasing shortness of breath the past few days at rest and with activity and also feels like his heart is beating out of his chest.  He also has 2-3 + bilateral lower extremity edema.', 'Samuel "Sam" ', 'Dixsen', '1956-05-10', 'Full', 5, 10, 92, NULL, 'English', 'Medicare', 'Retired', 'd8566186-5479-4874-8c22-470e8b57ed68', 'Baptist', false, 'ADHF', 'William Jones, MD', 0, '06:00:00', '{Hypertension,Hyperlipidemia,GERD,"HFrEF (dx 2017; last EF 30–35% from outpatient echo 2024)","CAD with remote MI history","MI #1 at age 56 (~2011) – PCI/stent per history","MI #2 at age 61 (~2016) – PCI per history"}', '{"Appendectomy (age 24)","Cardiac cath with stents (2011, 2016)"}', '{"Penicillin (rash)"}', '{"Tobacco: Quit 8 years ago (25 pack-year history)","Alcohol: 1–2 drinks/week","Drugs: Denies"}', '{"Lives alone  two-story home; independent baseline; decreased activity tolerance x 1–2 weeks"}', false, '2026-06-19 16:26:00.75+00', '2026-06-19 16:25:58.816+00', 'Paul Dixsen', 'Brother', '(555)-210-8976', '[{"intake": 0, "output": 0, "blockId": 1}, {"intake": 0, "output": 0, "blockId": 2}, {"intake": 0, "output": 0, "blockId": 3}, {"intake": 0, "output": 0, "blockId": 4}]');
