INSERT INTO "public"."cases_json_blobs" ("id", "payload", "title", "created_at", "updated_at") VALUES
	('60554715-a039-4112-9af6-d490741deb75', '"{\"demographics\":{\"DOBDay\":\"22\",\"DOBMonth\":\"March\",\"admissionDateOffest\":\"0\",\"admissionTime\":\"04:14\",\"admittingDiagnosis\":\"Hyponatremia\",\"age\":\"72\",\"attendingProviderName\":\"Chen\",\"attendingProviderTitle\":\"MD\",\"codeStatus\":\"Full\",\"dosingWeight\":\"75\",\"employment\":\"Retired Teacher\",\"firstName\":\"Harold\",\"heightFeet\":\"5\",\"heightInches\":\"11\",\"insurance\":\"Medicare\",\"language\":\"English\",\"needsInterpreter\":false,\"lastName\":\"Adams\",\"precautions\":\"Contact\",\"relationshipStatus\":\"Married\",\"religion\":\"NA\",\"summary\":\"Harold Adams is a 72-year-old male who recently returned from a Caribbean cruise. He came to the emergency department reporting ongoing nausea and vomiting for 3 days. He has not been eating or drinking. He presents with dizziness and fatigue. He has not urinated much in the past 24 hours.\",\"contact\":\"Linda Adams\",\"contactRelationship\":\"Wife\"},\"history\":{\"medicalHistory\":[\"HTN\",\"GERD\"],\"surgicalHistory\":[\"Appendectomy (1998)\"],\"familyHistory\":[{\"relation\":\"Mother\",\"condition\":\"Type 2 DM\"},{\"relation\":\"Father\",\"condition\":\"Heart Failure\"}],\"socialHistory\":[\"Non-Smoker\",\"Wine 1-2 glasses/week\"],\"livingSituation\":[\"Lives with Spouse\"],\"allergies\":[\"Seasonal Allergies\"],\"alerts\":[\"NPO Status\",\"Orthostatic Hypotension Risk\",\"High Risk for Falls - Morse score > 45\",\"Pressure Injury Risk (Braden <18)\"]},\"notes\":[{\"title\":\"Progress Note\",\"author\":\"Dr. Adler\",\"specialty\":\"Internal Medicine\",\"timeOffset\":-120,\"content\":\"<h2><u>Subjective:</u> </h2><h2>Patient presented with 3 days of nausea, vomiting, and diarrhea following return from cruise. Reports dizziness, fatigue, and poor oral intake.</h2><p></p><h2><u>Objective:</u> </h2><h2>Vitals: T 37.2 C, HR 88, BP 118/72, RR 18, SpO2 97% RA</h2><h2>Dry mucous membranes, skin tenting noted</h2><h2>Alert and oriented x3</h2><h2>Abdomen soft, slightly tender, hyperactive bowel sounds</h2><h2>Labs:</h2><h2>Na+ 125mEq/L</h2><h2>K+ 3.7 mEq/L</h2><h2>BUN 25 mg/dL, Creatinine 1.1 mg/dL</h2><h2>WBC 11,000</h2><h2>Lactic acid 1.3 mmol/L</h2><p></p><h2><u>Assessment:</u></h2><h2>Hyponatremia likely secondary to fluid losses. Mild dehydration. Hemodynamically stable.</h2><p></p><h2><u>Plan:</u></h2><h2>Start NS 75mL/hr</h2><h2>Advance diet as tolerated</h2><h2>Monitor electrolytes every AM</h2><h2>Fall precautions for dizziness</h2><h2>PT/OT eval due to weakness</h2><p></p>\",\"excludedFromPresim\":false},{\"title\":\"Nursing Note\",\"author\":\"Jane Smith, RN\",\"specialty\":\"Nursing\",\"timeOffset\":-240,\"content\":\"<h2><u>Situation:</u></h2><h2>Mr. Adams is a 72-year-old male with nausea/vomiting x3days, hypotension, and hyponatremia</h2><h2></h2><h2><u>Background:</u></h2><h2>History of GERD and HTN. Vomiting started after return from cruise.</h2><h2></h2><h2><u>Assessment:</u></h2><h2>Orthostatic hypotension noted:</h2><h2>Lying BP: 112/68 HR 98</h2><h2>Sitting BP: 100/60 HR 108</h2><h2>Standing BP: 92/58 HR 118</h2><h2>Dry mucous membranes, poor skin turgor, decreased urine output, Na+ 125</h2><p></p><h2><u>Recommendation:</u></h2><h2>Continue fluids</h2><h2>Reassess orthostatics post-fluid challenge</h2><h2>Maintain contact precautions for GI rule out</h2><h2>Consider provider update for sodium trend and standing BP</h2><p></p>\",\"excludedFromPresim\":false},{\"title\":\"Admission Note\",\"author\":\"Dr. Chen\",\"specialty\":\"Emergency Medicine\",\"timeOffset\":-360,\"content\":\"<p>Chief Complaint: “Vomiting and diarrhea for several days, feeling dizzy.”</p><p></p><p>History of Present Illness: 72-year-old male presenting after returning from a cruise 3 days ago. Reports persistent nausea, vomiting, and watery diarrhea since returning home. States he has been unable to tolerate solid food and has had minimal oral intake. Reports dizziness when standing and significant fatigue. Denies chest pain or shortness of breath. No blood in stool. Stool pathogen studies pending.</p><p></p><p>Past Medical History: Hypertension, GERD</p><p></p><p>Medications:</p><p>Lisinopril 10 mg daily</p><p>Omeprazole 20 mg daily</p><p></p><p>Allergies: No known drug allergies</p><p></p><p>Physical Examination:</p><p>General: Appears fatigued, mildly dehydrated</p><p>Neuro: Alert and oriented ×3</p><p>HEENT: Dry mucous membranes</p><p>Cardiac: Regular rate and rhythm</p><p>Respiratory: Clear breath sounds bilaterally</p><p>Abdomen: Soft, mild diffuse tenderness, hyperactive bowel sounds</p><p>Skin: Warm, decreased turgor<br></p><p>ED Vital Signs:</p><p>T: 37.6°C, HR: 90, BP: 116/70, RR: 18, SpO₂: 96% RA</p><p></p><p>ED Laboratory Results:</p><p>Na⁺ 125 mEq/L</p><p>K⁺ 3.7 mEq/L</p><p>Cl⁻ 94 mEq/L</p><p>BUN 25 mg/dL</p><p>Creatinine 1.1 mg/dL</p><p>WBC 11,000 /µL</p><p>Lactic acid 1.3 mmol/L<br></p><p>ED Treatment Provided: 1 L Normal Saline IV bolus. Ondansetron 4 mg IV for nausea. Basic metabolic panel and CBC obtained. Patient monitored for several hours.</p><p></p><p>Assessment:</p><p>Hyponatremia and dehydration likely secondary to gastrointestinal illness. Patient stable but symptomatic with dizziness and electrolyte imbalance.<br></p><p>Plan:</p><p>Admit to medical-surgical floor for IV fluids, electrolyte monitoring, and observation.</p>\",\"excludedFromPresim\":false}],\"orders\":[{\"category\":\"Laboratory\",\"title\":\"Basic Metabolic Panel (BMP)\",\"status\":\"Active\",\"details\":\"Collect Basic Metabolic Panel (BMP).\",\"orderingProvider\":\"Dr. John Smith, MD\",\"important\":true,\"visibleInPresim\":true},{\"important\":false,\"category\":\"Respiratory\",\"title\":\"Incentive Spirometry\",\"details\":\"Instruct patient to use incentive spirometer 10 times per hour while awake. Document effort and results\",\"status\":\"Active\",\"orderingProvider\":\"Dr. Azzedine Habz\",\"visibleInPresim\":true},{\"category\":\"Nursing\",\"title\":\"Vital Signs Monitoring (q4h)\",\"status\":\"Active\",\"details\":\"Monitor BP, HR, RR, Temp, SpO₂ every 4 hours. Notify provider for Temp > 38.0°C (100.4°F), Systolic BP > 160 mmHg or < 100 mmHg, HR > 110 bpm or < 50 bpm.\",\"orderingProvider\":\"Dr. John Smith, MD\",\"important\":true,\"visibleInPresim\":true},{\"category\":\"Nursing\",\"title\":\"Insert and Maintain IV\",\"status\":\"Active\",\"details\":\"\",\"orderingProvider\":\"Dr. John Smith, MD\",\"important\":true,\"visibleInPresim\":true},{\"category\":\"Nursing\",\"title\":\"Activity: As Tolerated\",\"status\":\"Active\",\"details\":\"Encourage patient activity as tolerated. Assist with ambulation as needed.\",\"orderingProvider\":\"Dr. John Smith, MD\",\"important\":false,\"visibleInPresim\":true},{\"important\":false,\"category\":\"Nursing\",\"title\":\"Fall Risk Precautions\",\"status\":\"Active\",\"details\":\"Implement standard fall risk protocol. Ensure bed in low position and call light within reach.\",\"orderingProvider\":\"Dr. John Smith, MD\",\"visibleInPresim\":true},{\"category\":\"Respiratory\",\"title\":\"Oxygen Therapy\",\"details\":\"Administer supplemental oxygen as needed to maintain SpO2 92% and above.\",\"status\":\"Active\",\"orderingProvider\":\"Dr. Chen\",\"important\":true,\"visibleInPresim\":true},{\"category\":\"Nursing\",\"title\":\"Cardiac Monitoring\",\"details\":\"continuous- acute electrolyte imbalance\",\"status\":\"Active\",\"orderingProvider\":\"Dr. Chen\",\"important\":true,\"visibleInPresim\":true},{\"category\":\"Nursing\",\"title\":\"Orthostatic Vital Signs\",\"details\":\"Daily- lying, sitting, standing- BP and HR. \",\"status\":\"Active\",\"orderingProvider\":\"Dr. Chen\",\"important\":true,\"visibleInPresim\":true},{\"category\":\"Diet\",\"title\":\"Diet\",\"details\":\"NPO except medications until nausea improves\",\"status\":\"Active\",\"orderingProvider\":\"Dr. Chen\",\"important\":true,\"visibleInPresim\":true},{\"category\":\"Nursing\",\"title\":\"Intake & Output\",\"details\":\"q8 hours\",\"status\":\"Active\",\"orderingProvider\":\"Dr. Chen\",\"important\":true,\"visibleInPresim\":true}],\"labs\":{\"data\":[{\"field\":\"Metabolic\",\"unit\":\"\",\"rowType\":\"divider\"},{\"0\":\"\",\"field\":\"Sodium\",\"unit\":\"(mEq/L)\",\"rowType\":\"results\",\"normalRange\":{\"low\":135,\"high\":145},\"-360\":\"125\"},{\"field\":\"Potassium\",\"unit\":\"(mEq/L)\",\"rowType\":\"results\",\"normalRange\":{\"low\":3.5,\"high\":5},\"criticalRange\":{\"low\":3,\"high\":6},\"-360\":\"3.7\"},{\"field\":\"Chloride\",\"unit\":\"(mEq/L)\",\"rowType\":\"results\",\"normalRange\":{\"low\":95,\"high\":105},\"-360\":\"94\"},{\"field\":\"BUN\",\"unit\":\"(mg/dL)\",\"rowType\":\"results\",\"normalRange\":{\"low\":7,\"high\":20},\"-360\":\"25\"},{\"field\":\"Creatinine\",\"unit\":\"(mg/dL)\",\"rowType\":\"results\",\"normalRange\":{\"low\":0.6,\"high\":1.2},\"-360\":\"1.1\"},{\"field\":\"Glucose\",\"unit\":\"(mg/dL)\",\"rowType\":\"results\",\"normalRange\":{\"low\":70,\"high\":100},\"-360\":\"108\"},{\"field\":\"CO2\",\"unit\":\"(mEq/L)\",\"rowType\":\"results\",\"normalRange\":{\"low\":23,\"high\":30},\"-360\":\"94\"},{\"field\":\"Calcium\",\"unit\":\"(mg/dL)\",\"rowType\":\"results\",\"normalRange\":{\"low\":8.5,\"high\":10.5},\"-360\":\"9.1\"},{\"field\":\"Lactate\",\"unit\":\"(mmol/L)\",\"rowType\":\"results\",\"normalRange\":{\"low\":0.5,\"high\":1},\"-360\":\"1.3\"},{\"field\":\"HbA1c\",\"unit\":\"%\",\"rowType\":\"results\",\"normalRange\":{\"low\":4,\"high\":5.6}},{\"field\":\"Hematology\",\"unit\":\"\",\"rowType\":\"divider\"},{\"field\":\"RBC\",\"unit\":\"(10⁶/µL)\",\"rowType\":\"results\",\"normalRange\":{\"low\":4,\"high\":6},\"-360\":\"6.2\"},{\"field\":\"Hemoglobin\",\"unit\":\"(g/dL)\",\"rowType\":\"results\",\"normalRange\":{\"low\":12,\"high\":17.5},\"-360\":\"15.2\"},{\"field\":\"Hematocrit\",\"unit\":\"(%)\",\"rowType\":\"results\",\"normalRange\":{\"low\":36,\"high\":54},\"-360\":\"46\"},{\"field\":\"MCV\",\"unit\":\"(fL)\",\"rowType\":\"results\",\"